import sys

data = sys.stdin.read().split()
n0 = int(data[0])
def isp(v):
    if v < 2:
        return False
    d = 2
    while d * d <= v:
        if v % d == 0:
            return False
        d += 1
    return True
c = 0
for x in range(2, n0 - 1):
    if isp(x) and isp(x + 2):
        c += 1
print(c)

